public class InnerDestinationEndpointStandardDestinationEndpointProtocolConfigurationFactory(Action<Humidifier.MediaConnect.DestinationEndpointTypes.StandardDestinationEndpointProtocolConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.MediaConnect.DestinationEndpointTypes.StandardDestinationEndpointProtocolConfiguration>
{

    internal InnerDestinationEndpointSrtCallerStandardDestinationEndpointConfigurationFactory SrtCallerFactory { get; set; }

    internal InnerDestinationEndpointSrtListenerStandardDestinationEndpointConfigurationFactory SrtListenerFactory { get; set; }

    internal InnerDestinationEndpointRistStandardDestinationEndpointConfigurationFactory RistFactory { get; set; }

    internal InnerDestinationEndpointRtpStandardDestinationEndpointConfigurationFactory RtpFactory { get; set; }

    protected override Humidifier.MediaConnect.DestinationEndpointTypes.StandardDestinationEndpointProtocolConfiguration Create()
    {
        var standardDestinationEndpointProtocolConfigurationResult = CreateStandardDestinationEndpointProtocolConfiguration();
        factoryAction?.Invoke(standardDestinationEndpointProtocolConfigurationResult);

        return standardDestinationEndpointProtocolConfigurationResult;
    }

    private Humidifier.MediaConnect.DestinationEndpointTypes.StandardDestinationEndpointProtocolConfiguration CreateStandardDestinationEndpointProtocolConfiguration()
    {
        var standardDestinationEndpointProtocolConfigurationResult = new Humidifier.MediaConnect.DestinationEndpointTypes.StandardDestinationEndpointProtocolConfiguration();

        return standardDestinationEndpointProtocolConfigurationResult;
    }
    public override void CreateChildren(Humidifier.MediaConnect.DestinationEndpointTypes.StandardDestinationEndpointProtocolConfiguration result)
    {
        base.CreateChildren(result);

        result.SrtCaller ??= SrtCallerFactory?.Build();
        result.SrtListener ??= SrtListenerFactory?.Build();
        result.Rist ??= RistFactory?.Build();
        result.Rtp ??= RtpFactory?.Build();
    }

} // End Of Class

